import{createClient}from'https://esm.sh/@supabase/supabase-js@2.57.0';
const S=createClient('https://zdmpcvlmjmsapydaljms.supabase.co','sb_publishable_eGELBhmMhdPu4g4Sw5g2xg_3oO7g8ib',{auth:{persistSession:false,autoRefreshToken:false}}),E='https://zdmpcvlmjmsapydaljms.supabase.co/functions/v1/private-admin-v2';
let adminPassword='';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const msg=(x,err=false)=>{const e=$('msg');e.textContent=x;e.className='status'+(err?' error':'')};
async function api(path,opts={}){const r=await fetch(E+'/'+path,{...opts,headers:{'Content-Type':'application/json','x-admin-password':adminPassword}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'Request failed');return d}
async function toggleOrg(id,enabled){const b=document.querySelector(`[data-org-toggle="${id}"]`);if(b){b.disabled=true;b.textContent='Saving…'}try{await api('organization-status',{method:'POST',body:JSON.stringify({organizationId:id,enabled})});await load();msg(enabled?'Organization enabled.':'Organization disabled.')}catch(x){if(b){b.disabled=false;b.textContent=enabled?'Enable':'Disable'}msg(x.message||String(x),true)}}
async function deleteOrg(id,name){if(!confirm(`Delete organization “${name}”? This permanently deletes its staff accounts and organization data.`))return;try{await api('delete-organization',{method:'POST',body:JSON.stringify({organizationId:id})});await load();msg('Organization deleted.')}catch(x){msg(x.message||String(x),true)}}
async function load(){const rows=await api('organizations');$('orgs').innerHTML=rows.map(x=>`<div class="cred"><span><strong>${esc(x.name)}</strong><small class="muted"> ${esc(x.slug)}</small></span><span style="display:flex;align-items:center;gap:10px;flex-wrap:wrap"><b>${x.enabled?'Enabled':'Disabled'}</b><button type="button" data-org-toggle="${esc(x.id)}" onclick="window.__toggleOrg('${esc(x.id)}',${!x.enabled})">${x.enabled?'Disable':'Enable'}</button><button type="button" onclick="window.__deleteOrg('${esc(x.id)}','${esc(x.name).replace(/'/g,"\\'")}')">Delete</button></span></div>`).join('')||'No organizations yet.'}
window.__toggleOrg=toggleOrg;window.__deleteOrg=deleteOrg;
$('lf').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),p=String(f.get('password')||'');if(!p)return msg('Enter the Private Admin Password.',true);adminPassword=p;const b=e.currentTarget.querySelector('button');b.disabled=true;b.textContent='Checking…';try{await load();$('login').classList.add('hidden');$('app').classList.remove('hidden');msg('')}catch(x){adminPassword='';msg(x.message||String(x),true)}finally{b.disabled=false;b.textContent='Enter Admin'}});
$('of').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget),businessName=String(form.get('organizationName')||''),ownerName=String(form.get('ownerName')||''),b=e.currentTarget.querySelector('button');b.disabled=true;b.textContent='Generating…';try{const data=await api('owners',{method:'POST',body:JSON.stringify(Object.fromEntries(form))});$('result').classList.remove('hidden');const values=[['Business Name',businessName],['Owner Name',ownerName],['Station ID',data.station_slug],['Login Code',data.owner_code],['Password',data.ownerPassword]];$('result').innerHTML=`<h2>Owner credentials generated</h2><p class="muted">Save all 5 values now. The Owner uses Station ID + Login Code + Password to sign in.</p>${values.map(([k,v])=>`<div class="cred generated"><span>${k}</span><span><b>${esc(v)}</b> <button type="button" data-copy="${esc(v)}">Copy</button></span></div>`).join('')}`;$('result').querySelectorAll('[data-copy]').forEach(x=>x.onclick=()=>navigator.clipboard?.writeText(x.dataset.copy));e.currentTarget.reset();await load()}catch(x){$('result').classList.remove('hidden');$('result').innerHTML=`<p class="error">${esc(x.message||String(x))}</p>`}finally{b.disabled=false;b.textContent='Generate Owner login credentials'}});
$('logout').onclick=()=>{adminPassword='';$('app').classList.add('hidden');$('login').classList.remove('hidden');$('lf').reset();$('of').reset();$('result').classList.add('hidden');msg('')};
